 "작업 공간과 프로젝트가 정해지지 않았어요. 설정 › 고급 › 연결에서 범위를 먼저 정해 주세요.": "L'espace de travail et le projet ne sont pas définis. Définissez d'abord la portée dans Réglages › Avancé › Connexion.",
 "기억 후보가 생기거나 기억이 승인·변경될 때 다른 서비스로 알림을 보내요.": "Envoie une notification à un autre service lorsqu'un candidat de souvenir apparaît ou qu'un souvenir est approuvé ou modifié.",
