 "고친 문장을 검토 대기에 넣어요. 검토 후 새 기억으로 승인할 수 있어요.": "La phrase corrigée est placée en attente de révision. Après relecture, vous pourrez l'approuver comme nouvelle mémoire.",
 "검토 대기에 추가해요. 승인한 뒤 모든 에이전트가 자료로 써요.": "Ajouté à la révision. Une fois approuvé, tous les agents pourront l'utiliser comme référence.",
 "이미 수집한 내용이에요. 기억 목록에서 상태를 확인하세요.": "Ce contenu a déjà été collecté. Vérifiez son état dans la liste des mémoires.",
 "검토 대기에 들어갔어요. 기억 › 검토 대기에서 승인하면 저장돼요.": "Ajouté à la révision. Approuvez-le dans Memory › En attente de révision pour l'enregistrer.",
 "기억 검토 규칙 보기": "Voir les règles de révision des mémoires",
 "새로 수집한 모든 기억": "Toutes les mémoires nouvellement collectées",
 "AI 역할": "Rôle de l'IA",
