 "되돌아가는 선이에요. 최대 2번까지 다시 돌아요. 선을 눌러 횟수와 갈래 이름을 바꿀 수 있어요.": "C'est une ligne de retour en arrière. Elle boucle jusqu'à 2 fois. Cliquez sur la ligne pour modifier le nombre de fois et le nom de la branche.",
 "노드마다": "Par nœud",
 "없어요": "Aucun",
 "워크플로우 설정": "Réglages du workflow",
 "노드 설정": "Réglages du nœud",
 "노드를 누르면 여기서 고쳐요. 출력 점을 끌어 다음 노드에 이어요. 앞 노드로 이으면 되돌아가는 선이 돼요. 선을 누르면 선 설정이 열려요. 휠로 확대·축소하고, 휠 클릭이나 스페이스를 누른 채 끌면 화면이 움직여요.": "Cliquez sur un nœud pour le modifier ici. Faites glisser le point de sortie pour le relier au nœud suivant ; le relier à un nœud précédent crée une ligne de retour en arrière. Cliquez sur une ligne pour ouvrir ses réglages. Zoomez avec la molette ; faites glisser avec un clic molette ou en maintenant Espace pour déplacer la vue.",
 "노드": "Nœud",
 "되돌아가는 선": "Ligne de retour en arrière",
 "고르세요": "Choisissez",
 "출력이 {\"ok\": true/false, …}면 통과·실패 갈래로 나뉘어요. 처음 한 번은 빌드에 1~2초, 30초 안에 끝나야 해요. 토큰은 들지 않아요.": "Si la sortie est {\"ok\": true/false, …}, elle se divise en branches réussite et échec. La première fois, la compilation prend 1 à 2 secondes et l'exécution doit se terminer en 30 secondes. Aucun jeton n'est utilisé.",
 "배포·게시처럼 되돌릴 수 없는 단계 바로 앞에 두세요. 답이 올 때까지 멈춰요.": "Placez-le juste avant une étape irréversible, comme un déploiement ou une publication. Il reste en pause jusqu'à l'arrivée d'une réponse.",
