 "검사 기록 없음": "Aucun historique de vérification",
 "알림만이면 PR에 코멘트만 남겨요. 막으면 blocking 지적이 있는 PR은 검사가 실패해 병합할 수 없어요.": "« Notifier seulement » laisse uniquement des commentaires sur la PR. En mode blocage, la vérification échoue pour les PR avec des problèmes bloquants (blocking) et elles ne peuvent pas être fusionnées.",
 "PR에 코멘트만 남겨요": "Laisse uniquement des commentaires sur la PR",
 "심각한 건 막기": "Bloquer si c'est grave",
