 "세션 ID": "ID de session",
 "이 서버는 아직 대화 보기를 지원하지 않아요.": "Ce serveur ne permet pas encore d'afficher les conversations.",
 "이 세션은 보관된 대화가 없어요. 대화 원문은 수집된 뒤 7일 동안만 보관돼요.": "Cette session n'a aucune conversation archivée. Le texte original n'est conservé que 7 jours après sa collecte.",
 "보관된 대화가 만료됐거나 지워졌어요.": "La conversation archivée a expiré ou a été supprimée.",
 "이 형식의 대화는 아직 볼 수 없어요.": "Les conversations de ce format ne peuvent pas encore être affichées.",
 "길어서 앞부분만 보여요.": "Trop long : seul le début est affiché.",
 "보여 줄 대화가 없어요.": "Aucune conversation à afficher.",
 "대화": "Conversation",
 "지울 권한이 없어요.": "Vous n'avez pas l'autorisation de supprimer.",
