 "대화 닫기": "Fermer la conversation",
 "입력": "Entrée",
 "출력": "Sortie",
 "캐시 읽기": "Lecture du cache",
 "정보": "Infos",
 "고정 과제로 비교 실행": "Lancer la comparaison sur des tâches fixes",
 "관리 계정의 데스크톱 앱에서 비교를 실행할 수 있어요.": "La comparaison peut être lancée depuis l'application de bureau avec un compte administrateur.",
 "고정 비교 계획이 있는 검토 대기 버전에서 실행할 수 있어요.": "Disponible pour les versions en attente de revue qui ont un plan de comparaison fixe.",
 "서버를 다시 조회해 주세요.": "Veuillez interroger de nouveau le serveur.",
 "SSH 서버 이름을 확인해 주세요.": "Vérifiez le nom du serveur SSH.",
 "설정과 실행 기록을 확인하는 중…": "Vérification des paramètres et de l'historique d'exécution…",
 "이 버전의 고정 과제·실행 조건과 일치하는 평가 설정이 없어요.": "Aucun paramètre d'évaluation ne correspond aux tâches fixes et aux conditions d'exécution de cette version.",
 "평가 설정": "Paramètres d'évaluation",
 "비교 실행": "Lancer la comparaison",
 "동일 과제로 기존 버전과 후보를 비교해요. 실행만으로 승인·적용되지는 않아요.": "Compare la version candidate à la version existante sur les mêmes tâches. Lancer la comparaison n'approuve ni n'applique rien.",
 "불러오지 못했어요. SSH 연결과 평가 서버의 범위·API 설정을 확인해 주세요.": "Chargement impossible. Vérifiez la connexion SSH ainsi que la portée et les paramètres API du serveur d'évaluation.",
 "비교 실행 중이에요.": "Comparaison en cours.",
 "비교 결과를 저장했어요. 승인·적용은 별도로 진행해 주세요.": "Résultats de la comparaison enregistrés. Approuvez et appliquez séparément.",
 "저장된 결과 없이 실행이 끝났거나 중단됐어요. 재실행 전에 서버에서 실행 상태를 확인해 주세요.": "L'exécution s'est terminée ou arrêtée sans résultat enregistré. Vérifiez son état sur le serveur avant de la relancer.",
 "미달": "Non atteint",
 "평가 다시 읽기": "Recharger l'évaluation",
 "상태 확인": "Vérifier l'état",
 "실행 상태를 확인하는 중…": "Vérification de l'état de l'exécution…",
 "결과를 확인하지 못했어요. 같은 버튼으로 다시 확인하세요. 같은 실행 요청은 중복 실행하지 않아요.": "Impossible de confirmer le résultat. Utilisez le même bouton pour vérifier de nouveau. La même demande d'exécution ne sera pas lancée deux fois.",
 "교훈으로 개선안 만들기": "Créer une amélioration à partir des leçons",
 "개선안을 생성하는 중…": "Génération de l'amélioration…",
 "생성 결과를 확인하지 못했어요. 같은 요청으로 다시 확인하세요. 완료된 요청은 새로 생성하지 않아요.": "Impossible de confirmer le résultat de la génération. Vérifiez de nouveau avec la même demande. Une demande terminée ne sera pas régénérée.",
 "입력 다시 선택": "Resélectionner l'entrée",
 "보류 요청을 지우지 못했어요. 앱 저장 공간을 확인해 주세요.": "Impossible d'effacer la demande en attente. Vérifiez l'espace de stockage de l'application.",
 "처리 결과를 확인할 생성 요청이 있어요.": "Une demande de génération attend la vérification de son résultat.",
 "생성 결과 다시 확인": "Revérifier le résultat de la génération",
 "개선안 생성은 관리 계정에서 시작할 수 있어요.": "La génération d'améliorations ne peut être lancée que depuis un compte administrateur.",
 "보류 요청을 읽지 못했어요. 중복 생성을 막기 위해 새 요청을 시작하지 않아요. 앱 저장 공간을 확인해 주세요.": "Impossible de lire la demande en attente. Pour éviter une génération en double, aucune nouvelle demande ne sera lancée. Vérifiez l'espace de stockage de l'application.",
 "현재 기준 버전을 확인하는 중…": "Vérification de la version de référence actuelle…",
 "개선안 생성": "Générer l'amélioration",
 "현재 기준 버전을 읽지 못했어요. 접었다 다시 펼쳐 주세요.": "Impossible de lire la version de référence actuelle. Réduisez puis redéployez la section.",
 "개선안과 버전 검토": "Améliorations et revue des versions",
 "승인됨": "Approuvée",
 "과거 버전": "Ancienne version",
 "중단됨": "Arrêtée",
 "저장된 내용이 없어요.": "Rien n'est enregistré.",
 "버전과 평가를 불러오는 중…": "Chargement des versions et des évaluations…",
 "검토할 버전": "Versions à revoir",
 "· 사용 중": "· en cours d'utilisation",
 "스킬 원문과 평가는 검토 자료예요. 조회만으로 승인되거나 실행되지 않아요.": "Le texte source du skill et les évaluations sont des éléments de revue. Les consulter n'approuve ni n'exécute rien.",
 "평가를 읽는 중…": "Lecture de l'évaluation…",
 "버전 원문": "Source de la version",
 "기존 버전 원문": "Source de la version précédente",
 "이 버전에 연결된 평가가 없어요.": "Aucune évaluation n'est liée à cette version.",
 "모델 자기평가": "Auto-évaluation du modèle",
