 "버전이나 평가를 읽지 못했어요. 권한·삭제·기록 변경 여부를 확인하고 다시 조회하세요.": "Impossible de lire les versions ou les évaluations. Vérifiez les autorisations, les suppressions et les modifications de l'historique, puis relancez la requête.",
