 "시험 종료": "Terminer l'essai",
 "시험을 종료하고 현재 반환 버전을 확인했어요. 이미 실행 중인 작업은 강제로 중단하지 않아요.": "L'essai est terminé et la version actuellement renvoyée est confirmée. Les tâches déjà en cours ne sont pas interrompues de force.",
