 "현재 후보나 보류 요청을 읽지 못해 새 시험을 준비할 수 없어요. 기존 기록은 확인할 수 있어요.": "Impossible de préparer un nouvel essai, car le candidat actuel ou la demande en attente n'a pas pu être lu. Vous pouvez toujours consulter les enregistrements existants.",
