 "미리보기": "Aperçu",
 "설치": "Installer",
 "GitHub 주소를 owner/repo 또는 owner/repo/경로 형태로 넣어 주세요.": "Saisissez l'adresse GitHub sous la forme owner/repo ou owner/repo/chemin.",
