 "넣을 에이전트를 골라 주세요.": "Choisissez les agents dans lesquels installer.",
 "설치를 요청했어요. 서버가 1분 안에 설치해요…": "Installation demandée. Le serveur l'installe en moins d'une minute…",
 "설치 결과를 아직 받지 못했어요. 잠시 뒤 스킬 목록을 확인해 주세요.": "Résultat de l'installation pas encore reçu. Consultez la liste des skills dans un instant.",
 "프로그램": "Programme",
 "자주 쓰는 서버": "Serveurs populaires",
 "상태 아이콘 색: 초록 정상 · 주황 확인 필요 · 빨강 연결 문제·멈춤": "Couleurs d'état : vert normal · orange à vérifier · rouge problème de connexion ou arrêt",
 "개선안 만들기 → 기존 버전과 비교 → 검토·승인 → 실제 작업에 시험 적용 순서로 진행해요.": "Créer une amélioration → comparer avec la version actuelle → examiner et approuver → l'essayer sur un vrai travail.",
