 "에이전트가 일할 때 꺼내 쓰는 작업 방법이에요.": "Des méthodes de travail que les agents utilisent quand ils travaillent.",
 "앱·메일·웹·문서에 쓰는 색·글꼴·규칙 모음이에요. 하나를 고르면 오른쪽에서 자세히 볼 수 있어요.": "Des ensembles de couleurs, de polices et de règles pour les apps, e-mails, sites web et documents. Choisissez-en un pour voir les détails à droite.",
 "슬라이드 프롬프트": "Prompts de diapositives",
 "변수 값을 채우고 바로 만들거나, ComfyUI 워크플로우로 보내요.": "Renseignez les variables et lancez la création tout de suite, ou envoyez-le vers un workflow ComfyUI.",
 "발표·보고용 슬라이드 프롬프트와 만드는 스크립트를 모아 둬요. 카드를 고르면 오른쪽에서 고치고 바로 만들 수 있어요.": "Rassemble des prompts de diapositives pour présentations et rapports, ainsi que les scripts qui les créent. Choisissez une carte pour la modifier à droite et la créer tout de suite.",
 "자주 쓰는 이미지 프롬프트를 예시 이미지와 함께 모아 둬요. 모델과 카테고리로 골라 보세요.": "Rassemble vos prompts d'images favoris avec des images d'exemple. Filtrez par modèle et par catégorie.",
 "플러그인은 스킬 + MCP + 명령을 한 번에 설치하는 묶음이에요.": "Un plugin installe en une fois des skills, des serveurs MCP et des commandes.",
 "에이전트가 쓰는 외부 도구 서버예요. 플러그인은 스킬·MCP를 묶어서 한 번에 설치해요.": "Des serveurs d'outils externes utilisés par les agents. Les plugins regroupent skills et MCP en une seule installation.",
