 "SSH 터널로 이 앱과 이어요": "Un tunnel SSH relie le serveur à cette application",
 "OpenSSH(또는 Git for Windows)가 이 PC에 있어야 해요.": "OpenSSH (ou Git for Windows) doit être installé sur ce PC.",
 "이름·모델·프롬프트를 적어 주세요. 제외할 것이나 스크립트는 오른쪽에서 더할 수 있어요. {변수}처럼 중괄호로 쓰면 변수가 돼요.": "Saisissez un nom, un modèle et un prompt. Vous pouvez ajouter des exclusions ou des scripts à droite. Écrivez entre accolades, comme {variable}, pour créer une variable.",
 "AI로 이름 짓기": "Nommer avec l’IA",
 "파일을 고르거나 이미지를 붙여 넣어요. 저장할 때 512KB 이하 WebP로 줄여요.": "Choisissez un fichier ou collez une image. Elle est réduite en WebP de 512 Ko maximum à l’enregistrement.",
 "추가 설정": "Réglages supplémentaires",
 "비워 두면 모델 기본값으로 만들어요.": "Laissez vide pour utiliser les valeurs par défaut du modèle.",
 "이름·출처·색·글꼴을 적고, 오른쪽에 쓰는 법과 규칙을 남겨 주세요. 키·토큰은 넣지 마세요.": "Saisissez le nom, la source, les couleurs et les polices, puis indiquez à droite le mode d’emploi et les règles. N’y mettez pas de clés ni de jetons.",
 "기본 정보": "Infos de base",
 "갤러리 카드에 보이는 이름과 설명이에요. 제품과 목적이 같은 것끼리 묶여요.": "Nom et description affichés sur la carte de la galerie. Les éléments du même produit et du même but sont regroupés.",
 "색과 글꼴": "Couleurs et polices",
 "색은 \"이름 #값\"을 한 줄에 하나씩 적어요.": "Écrivez les couleurs sous la forme « nom #valeur », une par ligne.",
 "이 디자인 시스템으로 화면을 만들 때 AI가 지킬 규칙이에요.": "Règles que l’IA respecte quand elle crée des écrans avec ce design system.",
 "다른 곳에서 수정됐으면 최신 내용을 확인한 뒤 다시 저장하세요.": "Si cela a été modifié ailleurs, vérifiez la dernière version, puis enregistrez de nouveau.",
 "영역 메뉴": "Menu de la zone",
 "연결 방법": "Mode de connexion",
 "Arkism 서버를 새 버전으로 올리면 디자인 시스템을 저장할 수 있어요.": "Mettez à jour le serveur Arkism pour pouvoir enregistrer des design systems.",
 "제품별·목적별로 디자인 시스템을 모아 둬요. 오른쪽 위 ‘디자인 시스템 추가’로 넣고, 이 앱의 실제 색·글자·부품은 ‘Arkism 토큰’에서 봐요.": "Rassemblez vos design systems par produit ou par usage. Ajoutez-en un avec « Ajouter un design system » en haut à droite ; les vraies couleurs, textes et composants de cette application se trouvent dans « Jetons Arkism ».",
 "아직 디자인 시스템이 없어요. 제품의 색·글꼴·규칙을 하나씩 추가해 보세요.": "Aucun design system pour l’instant. Ajoutez les couleurs, polices et règles d’un produit, une par une.",
 "최근 수정순": "Modifiés récemment",
 "최근 추가순": "Ajoutés récemment",
 "이름순": "Par nom",
 "스크립트 실행": "Exécuter le script",
 "복제했어요. 사본을 고쳐서 쓰세요.": "Dupliqué. Modifiez la copie pour l’utiliser.",
 "키나 토큰처럼 보이는 값이 있어 복제하지 않았어요.": "Non dupliqué : une valeur ressemble à une clé ou à un jeton.",
 "복제하지 못했어요. 이름이나 이미지 크기를 확인해 주세요.": "Duplication impossible. Vérifiez le nom ou la taille de l’image.",
 "복제하지 못했어요. 이름과 색을 확인해 주세요.": "Duplication impossible. Vérifiez le nom et les couleurs.",
 "쓰는 워크플로우($이름)를 정하면 그 워크플로우가 스크립트를 실행해요.": "Choisissez le workflow ($nom) à utiliser, et il exécutera le script.",
 "이전으로 되돌리기": "Revenir à la version précédente",
 "이전 내용으로 되돌렸어요.": "La version précédente a été restaurée.",
 "검토 대기에 들어갔어요. 기억 › 확인해 주세요에서 저장하면 되돌려져요.": "Envoyé en attente de relecture. Enregistrez-le dans Memory › À vérifier pour terminer la restauration.",
 "정리할 후보가 없었어요.": "Il n’y avait aucun candidat à nettoyer.",
 "이 계정은 후보를 정리할 수 없어요.": "Ce compte ne peut pas nettoyer les candidats.",
 "설정 파일 경로 복사": "Copier le chemin du fichier de configuration",
 "AI가 고쳐서 올리기": "Laisser l’IA corriger et envoyer",
 "고쳐서 올리기": "Corriger et envoyer",
 "한 번에 1분쯤 걸려요. 끝나면 에이전트를 새로 열어야 다시 붙어요.": "Chaque étape prend environ une minute. Rouvrez ensuite l’agent pour qu’il se reconnecte.",
 "‘다시 연결’을 누르거나, 서버의 에이전트에서 /mcp 를 열어 다시 인증해 주세요. 끝나면 1분 안에 여기 반영돼요.": "Cliquez sur « Se reconnecter », ou ouvrez /mcp dans l’agent sur le serveur et authentifiez-vous de nouveau. Le changement apparaîtra ici dans la minute.",
 "이미지 프롬프트": "Prompts d’image",
 "자체 업데이트": "mise à jour automatique",
 "버전이 바뀌었거나 이미 업데이트 중이에요. 새로고침해 주세요.": "La version a changé ou une mise à jour est déjà en cours. Veuillez actualiser.",
 "업데이트 중…": "Mise à jour…",
 "CLI 업데이트": "Mettre à jour la CLI",
 "기본값 · 서버 설정": "Par défaut · réglage du serveur",
 "이 서버는 아직 계정·모델 정보를 보내지 않아요. 서버를 새 버전으로 바꾸면 보여요.": "Ce serveur n’envoie pas encore les informations de compte et de modèle. Mettez le serveur à jour pour les voir.",
 "이 PC에 표시": "Afficher sur ce PC",
 "표시": "Afficher",
 "예시": "Exemple",
 "30일로 넓혀 보기": "Élargir à 30 jours",
 "최근 50건까지 보여요.": "Affiche jusqu’aux 50 plus récents.",
 "의도별": "Par intention",
 "순서대로": "Dans l’ordre",
 "의도별: 자동 라우팅이 켜져 있고 판정 모델이 있으면 판정 모델이 요청 내용과 모델 설명을 보고 그룹 안에서 골라요. 아니면 1번 모델로 가요.": "Par intention : si le routage automatique est activé et qu’un modèle juge est défini, ce modèle lit la demande et la description des modèles, puis choisit dans le groupe. Sinon, la demande va au modèle 1.",
 "순서대로: 늘 1번 모델로 보내고, 실패하면 다음 모델로 넘겨요.": "Dans l’ordre : envoie toujours au modèle 1, puis passe au suivant en cas d’échec.",
 "그룹에 꺼진 모델이 있어요. 모델을 켜거나 그룹에서 빼 주세요.": "Le groupe contient un modèle désactivé. Activez-le ou retirez-le du groupe.",
 "이름과 모델을 확인해 주세요. 그룹에는 모델이 하나 이상 있어야 해요.": "Vérifiez le nom et les modèles. Un groupe doit contenir au moins un modèle.",
 "다른 곳에서 먼저 바꿨어요. 새로고침한 뒤 다시 해 주세요.": "Quelqu’un l’a modifié ailleurs avant vous. Actualisez, puis réessayez.",
 "그룹을 저장했어요.": "Groupe enregistré.",
 "새 그룹": "Nouveau groupe",
 "쓸 수 있는 모델이 없어요 (그룹이 꺼졌거나 모델이 모두 꺼졌어요).": "Aucun modèle disponible (le groupe est désactivé ou tous ses modèles le sont).",
 "시험해 보기": "Essayer",
 "그룹 없이 · 모든 모델 중에서": "Sans groupe · parmi tous les modèles",
 "예: 이 함수에 테스트를 써 줘": "Ex. : Écris des tests pour cette fonction",
 "시험할 요청": "Demande à tester",
 "어디로 가나 보기": "Voir où cela va",
 "실제로 보내지 않고, 이 요청이면 어느 모델로 갈지만 물어봐요. 자동 라우팅이 켜져 있으면 판정 비용이 조금 들어요.": "Rien n’est envoyé : on demande seulement vers quel modèle irait cette demande. Si le routage automatique est activé, la décision du modèle juge a un petit coût.",
 "보낼 모델": "Modèle cible",
