 "같은 모델 자동으로 묶기": "Regrouper automatiquement les mêmes modèles",
 "같은 방식으로 라우팅되는 모델 묶음이에요. 에이전트가 모델 이름 대신 group/… 을 부르면 그룹 안에서 골라요.": "Ensemble de modèles routés de la même façon. Quand un agent demande group/… au lieu d’un nom de modèle, le choix se fait au sein du groupe.",
