 "같은 모델이 여러 계정에 있어 서버가 자동으로 묶었어요. 고치려면 그룹으로 만들어요.": "Le même modèle existe sur plusieurs comptes, donc le serveur l’a regroupé automatiquement. Créez-en un groupe pour le modifier.",
