 "모두": "Tous",
 "아직 라우터를 거친 요청이 없어요": "Aucune requête n'est encore passée par le routeur",
 "여기에는 Arkism 라우터가 모델을 골라 보낸 요청만 쌓여요. 라우팅을 켜고 워크플로우·하위 작업이 라우터로 모델을 고르면 요청 수·토큰·비용이 보여요.": "Seules les requêtes pour lesquelles le routeur Arkism a choisi un modèle apparaissent ici. Activez le routage : dès que des workflows ou sous-tâches choisissent leur modèle via le routeur, le nombre de requêtes, les tokens et le coût s'affichent.",
