 "자료": "Élément",
 "아직 없어요. 늘 알아야 하는 결정·스킬·문서를 넣어 두면, 부를 때마다 검색보다 먼저 들어가요.": "Rien pour l'instant. Ajoutez les décisions, compétences ou documents qu'il doit toujours connaître ; ils sont inclus avant la recherche à chaque appel.",
 "전체=다 넣기 · 요약=줄여서 넣기 · 참조=제목만 넣고 필요할 때 읽기 · 고정=그 버전만, 최신=바뀌면 따라가기": "Complet = tout inclure · Résumé = version raccourcie · Référence = titre seulement, lu au besoin · Figé = cette version uniquement, Dernière = suit les changements",
 "나중에": "Plus tard",
 "설정됨": "Configuré",
 "토큰 파일이 깨졌거나 다른 사용자도 읽을 수 있게 열려 있어요. 다시 만들면 고쳐져요.": "Le fichier du jeton est endommagé ou lisible par d'autres utilisateurs. En créer un nouveau règle le problème.",
 "모델 중계기": "Passerelle de modèles",
 "중계기 토큰을 다시 만들까요? 에이전트 설정에 새 토큰을 넣어요.": "Régénérer le jeton de la passerelle ? Le nouveau jeton sera ajouté aux réglages des agents.",
 "새 토큰을 만들고 에이전트 설정에 넣었어요. 중계기를 다시 켜면 예전 토큰은 막혀요.": "Nouveau jeton créé et ajouté aux réglages des agents. L'ancien sera bloqué dès que vous relancerez la passerelle.",
 "새 토큰을 만들었어요. 에이전트 설정에는 못 넣었어요 — 진단에서 고치기를 눌러 주세요.": "Nouveau jeton créé, mais il n'a pas pu être ajouté aux réglages des agents — cliquez sur Réparer dans Diagnostic.",
