 "새로 들어온 기억이 이미 있는 기억과 비슷해요. AI 제안을 보고 저장할지, 합칠지, 건너뛸지 골라 주세요.": "De nouveaux souvenirs ressemblent à ceux que vous avez déjà. Consultez la suggestion de l'IA et choisissez : enregistrer, fusionner ou ignorer.",
