 "모든 에이전트 · 참고 자료로": "Tous les agents · comme référence",
 "승인된 기억으로 AI가 새 주제를 묶었어요. 이 요약을 쓸까요?": "L'IA a regroupé des souvenirs approuvés en un nouveau sujet. Utiliser ce résumé ?",
