 "제안을 불러오는 중…": "Chargement des suggestions…",
 "검색과 맞는 제안이 없어요.": "Aucune suggestion ne correspond à votre recherche.",
 "AI 제안은 바로 적용하지 않아요. 고르면 그때 저장돼요.": "Les suggestions de l'IA ne sont pas appliquées tout de suite. Rien n'est enregistré tant que vous n'avez pas choisi.",
 "제안을 고르세요": "Choisissez une suggestion",
 "AI가 새 후보를 이미 있는 기억과 견줘 본 결과예요. 고르기 전엔 아무것도 바뀌지 않아요.": "Voici le résultat de la comparaison, par l'IA, d'un nouveau brouillon avec vos souvenirs existants. Rien ne change tant que vous n'avez pas choisi.",
 "비슷한 기억이 이미 있어요": "Un souvenir similaire existe déjà",
 "새 기억으로 저장 제안": "Suggère de l'enregistrer comme nouveau souvenir",
 "이미 있는 기억과 같아요": "Identique à un souvenir existant",
 "바뀜": "Modifié",
 "이미 있는 기억과 같음 → 건너뛰기 제안": "Identique à un souvenir existant → suggère de l'ignorer",
 "후보나 대상 기억이 그사이 바뀌어서 이 제안은 쓸 수 없어요. 무시하거나 새로 저장 목록에서 직접 골라 주세요.": "Le brouillon ou le souvenir cible a changé entre-temps : cette suggestion n'est plus utilisable. Ignorez-la ou choisissez vous-même dans la liste Nouveaux enregistrements.",
 "지금 내용을 읽지 못했어요. 다시 열어 주세요.": "Impossible de lire le contenu actuel. Veuillez rouvrir.",
 "수락": "Accepter",
 "고쳐서 수락": "Modifier et accepter",
 "고친 내용으로 수락": "Accepter avec ma modification",
 "이미 있는 기억": "Souvenir existant",
 "대상 기억": "Souvenir cible",
 "합친 뒤": "Après la fusion",
 "기존 기억에서 빠지는 말은 빨간 취소선, 새로 들어오는 말은 초록으로 보여요.": "Les mots retirés du souvenir existant apparaissent barrés en rouge, ceux qui sont ajoutés en vert.",
 "이렇게 하면": "Ce qui va se passer",
 "대상 기억은 이력으로 남고, 새 내용이 그 자리를 대신해요": "Le souvenir cible reste dans l'historique et le nouveau texte prend sa place",
 "새 내용을 기억으로 저장해요": "Enregistre le nouveau texte comme souvenir",
 "새 후보를 거절해요 · 지우지 않고 기록은 남아요": "Refuse le nouveau brouillon · il n'est pas supprimé, la trace est conservée",
 "제안만 닫혀요 · 후보는 새로 저장 목록에 그대로 남아요": "Seule la suggestion est fermée · le brouillon reste dans Nouveaux enregistrements",
 "제안을 닫았어요. 후보는 새로 저장 목록에 남아요.": "Suggestion fermée. Le brouillon reste dans Nouveaux enregistrements.",
 "후보를 건너뛰었어요.": "Brouillon ignoré.",
 "처리했어요.": "C'est fait.",
 "후보나 대상 기억이 바뀌어 이 제안은 낡았어요. 새로 불러왔어요.": "Le brouillon ou le souvenir cible a changé : cette suggestion est périmée. Les données ont été rechargées.",
 "이 계정은 제안을 처리할 수 없어요.": "Ce compte ne peut pas traiter les suggestions.",
 "복사했어요.": "Copié.",
 "복사하지 못했어요.": "Impossible de copier.",
 "잘라내기": "Couper",
 "붙여넣기": "Coller",
 "링크 복사": "Copier le lien",
 "Ctrl+V로 붙여넣어 주세요.": "Veuillez coller avec Ctrl+V.",
 "부르는 곳": "Appelants",
 "고친 내용은 버렸지만 지금 기억은 지우지 못했어요. 기억 목록에서 직접 지워 주세요.": "La modification a été abandonnée, mais le souvenir actuel n'a pas pu être supprimé. Supprimez-le depuis la liste des souvenirs.",
