 "실패 복구": "Récupération après échec",
 "기억 맥락": "Contexte du souvenir",
 "미분류": "Non classé",
 "함께 적용되는 상황을 기억해요.": "Mémorise les situations où cela s'applique aussi.",
 "적용 조건": "Conditions d'application",
 "조건이 기록되지 않았어요.": "Aucune condition enregistrée.",
 "근거 유형": "Type de preuve",
 "기억 유형": "Type de souvenir",
 "관측 시각": "Date d'observation",
 "기록되지 않았어요.": "Non enregistré.",
 "적용 시점": "Applicable à partir de",
 "불확실성": "Incertitude",
 "별도 설명이 없어요.": "Aucune explication supplémentaire.",
 "관측 없음": "Aucune observation",
 "이 버전의 기억이 도움이 됐는지 아직 확인되지 않았어요.": "On ne sait pas encore si cette version du souvenir a été utile.",
 "관측에서 실패": "Échec lors de l'observation",
 "사용자 평가 또는 자동 검사에 실패 결과가 있어요. 근거와 내용을 확인해 주세요.": "Une évaluation d'utilisateur ou une vérification automatique a échoué. Veuillez vérifier la preuve et le contenu.",
 "관측에서 통과": "Réussite lors de l'observation",
 "사용자 평가 또는 자동 검사에 통과했어요. 모든 상황에서 유용하다는 뜻은 아니에요.": "Une évaluation d'utilisateur ou une vérification automatique a réussi. Cela ne veut pas dire que c'est utile dans toutes les situations.",
 "판정 없는 관측": "Observation sans verdict",
 "관측은 남았지만 통과·실패 판정은 아직 없어요.": "Une observation a été enregistrée, mais il n'y a pas encore de verdict de réussite ou d'échec.",
 "모델 자기평가만 있음": "Auto-évaluation du modèle uniquement",
 "만든 모델의 자기평가예요. 독립된 사용 결과는 아직 없어요.": "Il s'agit de l'auto-évaluation du modèle qui l'a créé. Il n'y a pas encore de résultat d'utilisation indépendant.",
 "관측 대기": "En attente d'observation",
 "관측 기록됨": "Observation enregistrée",
 "추적 기록 없음": "Aucune trace",
 "기억 평가": "Évaluation du souvenir",
 "관측 결과를 불러오는 중…": "Chargement des observations…",
 "평가 추적": "Trace d'évaluation",
 "독립된 관측": "Observation indépendante",
 "Claude API 월 예산": "Budget mensuel de l'API Claude",
 "예산을 불러오는 중…": "Chargement du budget…",
 "월 전체": "Total du mois",
 "일반 처리": "Traitement général",
 "오늘 목표": "Objectif du jour",
 "오늘 상한": "Plafond du jour",
 "미정산 예약": "Réservations non réglées",
 "사용 확정액과 미정산 예약을 함께 계산해요. 실제 청구 금액과 다를 수 있어요.": "Le calcul inclut les dépenses confirmées et les réservations non réglées. Il peut différer de la facture réelle.",
 "오늘 목표를 넘었어요. 목표 초과만으로 처리를 차단하지 않으며 월 예산과 별도 설정한 상한은 계속 적용해요.": "L'objectif du jour est dépassé. Dépasser l'objectif ne bloque pas le traitement à lui seul ; le budget mensuel et le plafond défini séparément restent appliqués.",
 "오늘 목표는 지출 추이를 보는 기준이에요. 월 예산과 별도 설정한 상한은 계속 적용해요.": "L'objectif du jour sert de repère pour suivre les dépenses. Le budget mensuel et le plafond défini séparément restent appliqués.",
 "예산 다시 조회": "Recharger le budget",
 "생성 모델 기록": "Modèle générateur",
 "이 기록을 생성한 모델이에요. 모델 이름만으로 내용의 정확성이나 현재 기본 모델을 판단하지 않아요.": "Modèle qui a généré cet enregistrement. Le nom du modèle seul ne permet pas de juger l'exactitude du contenu ni de savoir s'il s'agit du modèle par défaut actuel.",
 "시험 진행 중": "Essai en cours",
 "실행과 독립 평가가 모두 확인되어야 다음 단계로 넘어가요.": "On ne passe à l'étape suivante qu'une fois les exécutions et l'évaluation indépendante confirmées.",
 "시험 조건 변경": "Conditions d'essai modifiées",
 "근거나 기준판이 달라져 현재 시험 후보를 사용할 수 없어요.": "La preuve ou la référence a changé : le candidat d'essai actuel ne peut pas être utilisé.",
 "종료는 시험 통과를 뜻하지 않아요.": "La fin de l'essai ne signifie pas qu'il a réussi.",
 "회귀 관측으로 시험 중단": "Essai arrêté après une régression",
 "문제가 관측되어 시험 후보 사용이 중단됐어요.": "Un problème a été observé : le candidat d'essai n'est plus utilisé.",
 "시험 기간 종료": "Période d'essai terminée",
 "기간이 끝났다는 이유만으로 성공 처리하지 않아요.": "Un essai n'est jamais considéré comme réussi simplement parce que le délai est écoulé.",
 "기본 버전으로 적용됨": "Appliquée comme version par défaut",
 "승격 뒤 회귀 여부는 계속 별도 관측으로 확인해요.": "Les régressions après la promotion continuent d'être vérifiées par une observation distincte.",
 "회귀 버전 차단 · 복구 미완료": "Version régressive bloquée · restauration non terminée",
 "문제가 있는 버전은 차단됐지만 기준판 복구는 아직 확인되지 않았어요.": "La version défectueuse est bloquée, mais la restauration de la version de référence n'est pas encore confirmée.",
 "기준판으로 복구됨": "Restaurée à la version de référence",
 "서버에서 기준판 선택을 확인했어요. 이미 실행 중인 작업의 복구를 뜻하지는 않아요.": "Le serveur a confirmé la sélection de la version de référence. Cela ne signifie pas que les tâches déjà en cours sont restaurées.",
 "자동 확인 중": "Vérification automatique en cours",
 "다음 확인 대기": "En attente de la prochaine vérification",
 "자동 확인 실패 · 재확인 필요": "Échec de la vérification automatique · nouvelle vérification nécessaire",
 "확인 작업 종료": "Tâche de vérification terminée",
 "현재 처리 상태를 확인하는 중…": "Vérification de l'état du traitement en cours…",
 "독립 평가 결과는 이 조회에서 확인되지 않아요.": "Les résultats de l'évaluation indépendante ne sont pas affichés par cette consultation.",
 "자동 확인 작업이 등록되어 있지 않아요.": "Aucune tâche de vérification automatique n'est enregistrée.",
 "처리 상태를 확인하지 못했어요": "Impossible de vérifier l'état du traitement",
 "권한이나 서버 상태를 확인한 뒤 다시 조회해 주세요.": "Vérifiez vos autorisations ou l'état du serveur, puis réessayez.",
 "자동 처리 상태": "État du traitement automatique",
 "처리 상태 다시 조회": "Actualiser l'état du traitement",
 "템플릿·설정으로 만들기": "Créer à partir d'un modèle ou de réglages",
 "AI 답을 읽지 못했어요. 다시 보내 주세요.": "Impossible de lire la réponse de l'IA. Veuillez renvoyer votre message.",
 "제목없음": "Sans titre",
