 "배경색": "Couleur de fond",
 "아바타": "Avatar",
 "아바타 고르기": "Choisir un avatar",
 "모델 아이콘 쓰기": "Utiliser l'icône du modèle",
 "답에 보였는지": "Présence dans la réponse",
 "아직 서버가 답에 보였는지 기록을 보내지 않았어요.": "Le serveur n'a pas encore envoyé de relevé de présence dans les réponses.",
 "질문할 때 찾아 넣은 기억의 문구가 답에 보였는지만 세요. 실제 활용 여부는 측정하지 않았고, 읽지 못한 대화 수는 이 통계에서 알 수 없어요.": "Compte uniquement si le texte des souvenirs retrouvés lors de la question apparaît dans la réponse. L'usage réel n'est pas mesuré, et ces statistiques n'indiquent pas le nombre de conversations non lues.",
 "답에 보인 기억이 아직 없어요.": "Aucun souvenir n'est encore apparu dans une réponse.",
 "답에 안 보여 확인할 기억": "Souvenirs absents des réponses à vérifier",
 "답에 안 보임": "Absent des réponses",
 "최근 호출 없음": "Aucun appel récent",
 "기억이 답에 보였는지는 PC 수집기가 보고하면 여기에 보여요. 실제 활용 여부는 측정하지 않아요.": "Le collecteur du PC indiquera ici si les souvenirs sont apparus dans les réponses. L'usage réel n'est pas mesuré.",
 "답에 안 보임 · 직접 검토": "Absent des réponses · à vérifier manuellement",
 "답에 보인 비율": "Taux de présence dans les réponses",
 "답에 보임": "Présent dans la réponse",
 "종류별로 답에 보인 비율": "Taux de présence dans les réponses par type",
 "전달한 기억 중 답에 보인 비율": "Part des souvenirs transmis présents dans les réponses",
 "재검토 예정일이 지났거나 최근에 잘 안 불리거나 답에 잘 안 보여요. 직접 확인해 주세요": "La date de réexamen est dépassée, ou ils sont peu appelés récemment ou peu présents dans les réponses. Veuillez les vérifier.",
 "승인 기록": "Historique d'approbation",
 "재검토 예정일이 지났거나 최근에 잘 안 불리거나 답에 잘 안 보이는 기억이에요. 실제 활용 여부와는 구분해요.": "Ces souvenirs ont une date de réexamen dépassée, ou sont peu appelés récemment ou peu présents dans les réponses. Cela diffère de l'usage réel.",
 "재검토 예정일 지남": "Date de réexamen dépassée",
 "확인하기": "Vérifier",
 "펼치면 서로 다른 원문 발화 수를 확인해요. 횟수는 승인이나 신뢰 점수가 아니에요.": "Développez pour voir le nombre de messages d'origine distincts. Le nombre n'est ni une approbation ni un score de confiance.",
 "각 문장의 조건과 예외를 확인하고 항목별로 결정해 주세요.": "Vérifiez les conditions et exceptions de chaque phrase, puis décidez élément par élément.",
 "원문 근거를 확인하는 중…": "Vérification de la source d'origine…",
 "재검토 예정일이 지났어요": "La date de réexamen est dépassée",
 "대화에서 기억할 만한 내용을 찾아요. 저장할지는 사람이 정해요.": "Cherche dans vos conversations ce qui mérite d'être retenu. C'est vous qui décidez de l'enregistrer.",
 "재검토 예정일이 지났어요. 내용이 아직 맞는지 직접 확인해 주세요.": "La date de réexamen est dépassée. Vérifiez si le contenu est toujours correct.",
 "최근 30일 동안 검색으로 전달된 기록이 없어요. 실제 활용 여부와 내용의 필요성은 따로 확인해 주세요.": "Aucune transmission par recherche n'a été enregistrée ces 30 derniers jours. Vérifiez séparément l'usage réel et l'utilité du contenu.",
 "기억 관리": "Gestion des souvenirs",
 "정정 또는 충돌 검토가 대기 중이에요. 기존 기억이 계속 전달될 수 있으니 먼저 확인해 주세요.": "Une correction ou un examen de conflit est en attente. Le souvenir existant peut encore être transmis ; veuillez d'abord le vérifier.",
 "다음 재검토": "Prochain réexamen",
 "예정일 없음": "Aucune date prévue",
 "사용 종료": "Utilisable jusqu'au",
 "만료일 없음": "Pas de date d'expiration",
 "재검토 예정일은 삭제·자동 승인·보관 연장과 별개예요.": "La date de réexamen est indépendante de la suppression, de l'approbation automatique et de la prolongation de conservation.",
 "원본 보관 상태는 별도로 확인할 수 있어요.": "L'état de conservation de l'original peut être vérifié séparément.",
 "원본 보관 확인": "Vérifier la conservation de l'original",
 "· 일부만 확인": "· vérification partielle",
 "원본 상태를 확인하지 못했어요. 보관 중이라고 간주하지 않아요.": "Impossible de vérifier l'état de l'original. Il n'est pas considéré comme conservé.",
 "재검토 예정일": "Date de réexamen",
 "재검토 예정일을 변경했어요.": "La date de réexamen a été modifiée.",
 "예정일 저장": "Enregistrer la date",
 "앞으로의 날짜를 선택해 주세요.": "Veuillez choisir une date à venir.",
 "예정일 해제": "Supprimer la date",
 "원문 확인": "Vérifier l'original",
 "AI가 쓴 이유와 실제 대화는 다를 수 있어요. 저장하기 전에 원문을 확인해 보세요.": "La raison donnée par l'IA peut différer de la vraie conversation. Vérifiez l'original avant d'enregistrer.",
