 "지시를 적어 주세요.": "Saisissez les instructions.",
 "@이름을 적어 주세요.": "Saisissez le @nom.",
 "@이름은 띄어쓰기 없이 글자·숫자·_·-로 적어 주세요.": "Pour le @nom, utilisez des lettres, chiffres, _ ou -, sans espaces.",
 "템플릿 이름을 적어 주세요.": "Saisissez un nom de modèle.",
 "서버의 SSH 키가 예전과 달라 접속을 막았어요. 관리자에게 새 지문을 확인한 뒤 다시 연결하세요.": "La clé SSH du serveur a changé, donc la connexion a été bloquée. Vérifiez la nouvelle empreinte auprès de l'administrateur avant de vous reconnecter.",
 "서버 지문 확인을 취소했어요. 접속하지 않았습니다.": "Vérification de l'empreinte du serveur annulée. Aucune connexion n'a été établie.",
 "서버 지문 확인이 필요해요. 다시 연결해 주세요.": "La vérification de l'empreinte du serveur est nécessaire. Reconnectez-vous.",
 "서버 지문을 가져오지 못했어요. 주소·포트와 SSH 연결을 확인하세요.": "Impossible de récupérer l'empreinte du serveur. Vérifiez l'adresse, le port et la connexion SSH.",
 "지문 확인 시간이 지났어요. 다시 연결해 주세요.": "Le délai de vérification de l'empreinte est dépassé. Reconnectez-vous.",
 "그사이 승인한 키가 바뀌었어요. 다시 연결해 주세요.": "La clé approuvée a changé entre-temps. Reconnectez-vous.",
 "저장한 서버 키를 확인할 수 없어 접속을 막았어요.": "La clé de serveur enregistrée n'a pas pu être vérifiée, donc la connexion a été bloquée.",
 "서버의 SSH 지문을 확인하세요": "Vérifiez l'empreinte SSH du serveur",
 "서버를 다시 설치했거나, 다른 서버에 연결되고 있을 수 있어요. 관리자에게 새 지문을 확인하기 전에는 접속하지 마세요.": "Le serveur a peut-être été réinstallé, ou vous êtes connecté à un autre serveur. Ne vous connectez pas avant d'avoir vérifié la nouvelle empreinte auprès de l'administrateur.",
 "서버 관리자에게 다른 연락 수단으로 아래 지문을 확인해 주세요. 확인 전에는 개인 키·비밀번호로 로그인하지 않아요.": "Vérifiez l'empreinte ci-dessous auprès de l'administrateur du serveur par un autre moyen de contact. Tant que ce n'est pas confirmé, votre clé privée et votre mot de passe ne sont pas utilisés pour vous connecter.",
 "키 종류": "Type de clé",
 "새 지문": "Nouvelle empreinte",
 "이전 지문": "Empreinte précédente",
