 "서버 답을 읽지 못했어요": "Impossible de lire la réponse du serveur",
 "서버가 이 앱이 읽을 수 없는 형식으로 답했어요. 앱과 서버의 Arkism 버전을 맞춰 주세요.": "Le serveur a répondu dans un format que cette app ne peut pas lire. Utilisez la même version d'Arkism sur l'app et sur le serveur.",
 "서버가 접속을 거절했어요": "Le serveur a refusé la connexion",
 "접속 토큰이나 이 계정의 권한을 확인해 주세요.": "Vérifiez le jeton d'accès ou les autorisations de ce compte.",
 "서버에 문제가 생겼어요": "Le serveur a rencontré un problème",
 "서버가 요청을 처리하지 못했어요. 잠시 뒤 다시 시도해 주세요.": "Le serveur n'a pas pu traiter la requête. Réessayez dans un instant.",
