 "서버 보고를 받지 못했어요": "Aucun rapport reçu du serveur",
 "서버 보고에 이 에이전트가 없어요": "Le rapport du serveur n'inclut pas cet agent",
 "이 서버는 에이전트 상태를 보고하지 않아요": "Ce serveur ne signale pas l'état des agents",
 "일부 목록을 불러오지 못했어요": "Certaines listes n'ont pas été chargées",
 "스킬 목록을 불러오지 못했어요": "Impossible de charger la liste des compétences",
