 "디자인 시스템 목록을 불러오지 못했어요": "Impossible de charger la liste des design systems",
 "불러오지 못한 목록": "Listes non chargées",
 "확인할 일을 불러오지 못했어요": "Impossible de charger les points à vérifier",
 "서버에 SSH로 연결": "Se connecter à un serveur via SSH",
 "이 PC에서 Arkism을 실행해요. 인터넷 없이도 되고, 기억은 이 PC에만 저장돼요.": "Exécute Arkism sur ce PC. Fonctionne sans internet, et les souvenirs restent uniquement sur ce PC.",
 "서버에서 돌고 있는 Arkism을 SSH로 이어요. 여러 PC가 같은 기억을 써요.": "Se connecte via SSH à l'Arkism qui tourne sur votre serveur. Plusieurs PC partagent les mêmes souvenirs.",
 "Arkism을 어디서 쓸까요?": "Où voulez-vous utiliser Arkism ?",
 "처음 한 번만 고르면 돼요. 나중에 설정 › 연결에서 바꿀 수 있어요.": "Vous ne choisissez qu'une seule fois. Vous pourrez le modifier plus tard dans Réglages › Connexion.",
 "저장 위치": "Emplacement de stockage",
 "사용자 지정": "Personnalisé",
 "기억·설정·토큰이 저장되는 폴더예요. 바꿔도 지금 데이터는 옮기지 않아요.": "Dossier où sont enregistrés les souvenirs, les réglages et les jetons. Le modifier ne déplace pas les données actuelles.",
 "폴더 경로": "Chemin du dossier",
 "빈 폴더의 전체 경로": "Chemin complet d'un dossier vide",
 "기본 위치에 있던 데이터는 그대로 남아요.": "Les données de l'emplacement par défaut restent en place.",
 "폴더 경로를 넣어 주세요.": "Saisissez un chemin de dossier.",
 "C:\\ 나 /로 시작하는 전체 경로를 넣어 주세요.": "Saisissez un chemin complet commençant par C:\\ ou /.",
 "파일이 아니라 폴더 경로를 넣어 주세요.": "Saisissez un chemin de dossier, pas un fichier.",
 "빈 폴더나 Arkism 데이터 폴더만 쓸 수 있어요.": "Seul un dossier vide ou un dossier de données Arkism peut être utilisé.",
 "이 폴더를 읽을 수 없어요.": "Ce dossier est illisible.",
 "이 폴더에 쓸 수 없어요. 권한을 확인해 주세요.": "Impossible d'écrire dans ce dossier. Vérifiez les autorisations.",
 "저장 위치를 바꿨어요.": "L'emplacement de stockage a été modifié.",
 "앱을 다시 열면 새 위치에서 시작해요.": "Arkism démarrera au nouvel emplacement à la prochaine ouverture de l'app.",
 "저장 위치를 읽지 못했어요.": "Impossible de lire l'emplacement de stockage.",
 "SSH 로그인이 거부됐어요. 이 PC에서 ‘ssh 주소’가 비밀번호 없이(SSH 키로) 되는지 확인하세요. 키가 없으면 인증 방식을 비밀번호로 바꾸세요.": "La connexion SSH a été refusée. Vérifiez que « ssh adresse » fonctionne sur ce PC sans mot de passe (avec une clé SSH). Sans clé, passez la méthode d'authentification sur mot de passe.",
 "비밀번호 로그인이 거부됐어요. 비밀번호를 확인하세요. 서버가 비밀번호 로그인을 막아 두었으면 SSH 키가 필요해요.": "La connexion par mot de passe a été refusée. Vérifiez le mot de passe. Si le serveur bloque la connexion par mot de passe, une clé SSH est nécessaire.",
 "비밀번호 로그인이 거부됐어요": "La connexion par mot de passe a été refusée",
 "비밀번호를 넣어 주세요.": "Saisissez le mot de passe.",
 "인증 방식": "Méthode d'authentification",
 "SSH 키": "Clé SSH",
 "비밀번호": "Mot de passe",
 "연결되면 이 PC의 키체인(자격 증명 관리자)에 저장해 다시 묻지 않아요. 비워 두면 저장된 비밀번호를 써요": "Une fois connecté, il est enregistré dans le trousseau de ce PC (Gestionnaire d'identifiants) et ne vous sera plus demandé. Laissez vide pour utiliser le mot de passe enregistré",
 "서버의 Git·스킬 화면은 이 연결로 돼요. 에이전트의 기억 수집은 SSH 키가 있어야 서버로 가요.": "Les écrans Git et Compétences du serveur passent par cette connexion. La collecte des souvenirs des agents n'atteint le serveur qu'avec une clé SSH.",
 "SSH 키 또는 ssh-agent로 로그인해요": "Se connecte avec une clé SSH ou ssh-agent",
 "저장된 비밀번호가 없어요. 비밀번호를 넣고 연결하세요.": "Aucun mot de passe enregistré. Saisissez le mot de passe et connectez-vous.",
 "SSH 키 또는 비밀번호로 접속해요. 비밀번호는 이 PC의 키체인에 저장해 다시 묻지 않고, 연결 끊기를 누르면 지금 연결된 서버의 비밀번호를 지워요.": "Se connecte avec une clé SSH ou un mot de passe. Le mot de passe est enregistré dans le trousseau de ce PC pour ne plus vous être demandé, et Se déconnecter supprime celui du serveur actuellement connecté.",
 "이 PC의 터미널에서 아래 명령으로 같은 비밀번호로 접속되는지 먼저 확인하세요.": "Vérifiez d'abord, dans un terminal de ce PC, que la commande ci-dessous permet de se connecter avec le même mot de passe.",
 "호스트": "Hôte",
 "포트": "Port",
 "포트는 1~65535 사이 숫자예요.": "Le port doit être un nombre entre 1 et 65535.",
 "필터": "Filtre",
 "GitHub에서 가져오기": "Importer depuis GitHub",
 "저장소 주소를 넣으면 스킬을 미리 보고 고른 곳에 설치해요.": "Saisissez l'adresse d'un dépôt pour prévisualiser ses compétences et les installer à l'endroit de votre choix.",
 "AI에게 새 스킬 제안 받기": "Demander à l'IA de suggérer de nouvelles compétences",
 "최근 기억에서 반복한 요청을 찾아 스킬 초안을 홈의 할 일에 올려요.": "Repère les demandes répétées dans les souvenirs récents et place des brouillons de compétences dans les tâches de Home.",
 "실행할 프로그램이나 https 주소로 추가해요. 자주 쓰는 서버를 골라 채울 수도 있어요.": "Ajoutez-en un avec un programme à exécuter ou une adresse https. Vous pouvez aussi choisir un serveur courant pour remplir les champs.",
