 "기본 검사는 늘 돌아요. 이 PC에 설치된 엔진 중 함께 돌릴 것을 고르세요.": "Le contrôle de base s’exécute toujours. Choisissez parmi les moteurs installés sur ce PC ceux à lancer avec lui.",
 "스킬 요약": "Résumé des compétences",
 "새 스킬이 들어오면 무엇을 언제 쓰는지 정리해요. ‘스킬 설명 그대로’는 SKILL.md 설명만 써요.": "Quand une nouvelle compétence arrive, résume à quoi elle sert et quand l’utiliser. « Description d’origine de la compétence » utilise uniquement la description de SKILL.md.",
 "스킬 요약 모델": "Modèle de résumé des compétences",
 "스킬 후보 찾기": "Recherche de compétences candidates",
