 "스킬 후보 수": "Candidats de compétences",
 "내 모델로 요약하려면 주소와 모델 이름이 필요해요.": "Pour résumer avec votre propre modèle, saisissez son adresse et son nom.",
 "새 스킬이 들어오면 무엇을 언제 쓰는지 정리해요.": "Quand une nouvelle compétence arrive, résume à quoi elle sert et quand l’utiliser.",
