 "사용량 확인 안 됨": "Utilisation non communiquée",
 "외부 실행기에는 읽기 작업만 보내요. 모델은 실행기 것을 쓰고, 비용은 실행기가 알려 줄 때만 보여요. 연결은 터미널에서 arkism crew backends add로 만들어요.": "Seules les tâches en lecture seule sont envoyées à un exécuteur externe. Il utilise son propre modèle, et le coût n’apparaît que si l’exécuteur le communique. Créez une connexion dans un terminal avec arkism crew backends add.",
