 "서버 설정": "réglage du serveur",
 "이 서버에 설치된 검사 엔진이 없어요. 기본 검사만 돌아요.": "Aucun moteur de vérification n'est installé sur ce serveur. Seule la vérification de base est effectuée.",
 "이 서버가 돌릴 수 있는 임베딩은 이것 하나예요. 바꾸려면 서버 설정을 바꾸고 기억을 다시 색인해야 해요.": "C'est le seul embedding que ce serveur peut exécuter. Pour le changer, il faut modifier le réglage du serveur et réindexer toutes les mémoires.",
 "서버에 연결해 쓰는 동안에는 서버가 정한 폴더 위치를 써요.": "Tant que vous êtes connecté à un serveur, les emplacements de dossiers définis par le serveur sont utilisés.",
 "아직 확인 안 됨": "Pas encore confirmé",
 "임베딩을 바꿀까요?\n저장하면 기억을 모두 다시 색인해요. 기억이 많으면 시간이 걸려요.": "Changer l'embedding ?\nÀ l'enregistrement, toutes les mémoires seront réindexées. Cela peut prendre du temps s'il y en a beaucoup.",
