 "겹치는 스킬": "Compétences qui se chevauchent",
 "같은 질문에 둘 다 맞다고 판정된 스킬이에요. 숫자는 각각 뽑힌 횟수예요. 자주 겹치면 설명에서 쓰는 때를 나누거나 하나로 합치세요.": "Compétences jugées toutes deux adaptées à la même question. Les nombres indiquent combien de fois chacune a été choisie. Si elles se chevauchent souvent, précisez dans leur description quand les utiliser, ou fusionnez-les en une seule.",
