 "전달 실패": "Échec de l'envoi",
 "전달됨": "Envoyé",
 "불러오지 못했어요. 연결과 접근 권한을 확인한 뒤 새로고침해 주세요.": "Impossible de charger. Vérifiez la connexion et les droits d'accès, puis actualisez.",
 "아직 최종 결과가 없어요.": "Le résultat final n'est pas encore disponible.",
 "단계 보기": "Voir les étapes",
 "부른 실행 결과": "Résultats des exécutions appelées",
 "@이름으로 부른 실행의 최종 결과와 전달 상태": "Résultat final et état d'envoi des exécutions appelées par @nom",
 "아직 @이름으로 부른 실행이 없어요.": "Aucune exécution appelée par @nom pour le moment.",
 "회의 결과": "Résultat de la réunion",
 "하위 실행": "Exécution enfant",
 "사람의 결정이 필요해요": "Une décision humaine est nécessaire",
 "최신 실행을 다시 열어 주세요.": "Veuillez rouvrir l'exécution la plus récente.",
 "중단을 요청했어요. 실제 종료 상태를 확인해 주세요.": "Arrêt demandé. Vérifiez l'état réel de la fin d'exécution.",
 "결정을 보냈어요. 실행 상태를 다시 확인해요.": "Décision envoyée. Nouvelle vérification de l'état de l'exécution.",
 "보내지 못했어요. 상태가 바뀌었거나 권한이 없을 수 있어요. 다시 열어 확인해 주세요.": "Envoi impossible. L'état a peut-être changé ou vous n'avez peut-être pas les droits. Rouvrez et vérifiez.",
 "대화로 전달": "Envoi dans la conversation",
 "보냈는지 확인되지 않아 자동으로 다시 보내지 않아요. 원래 대화와 저장된 메시지 영수증을 먼저 확인해 주세요.": "L'envoi n'est pas confirmé, il ne sera donc pas renvoyé automatiquement. Vérifiez d'abord la conversation d'origine et les accusés de réception des messages enregistrés.",
 "권한이나 대화 상태를 확인해 주세요. 전달을 복구하려고 작업을 다시 실행하지 마세요.": "Vérifiez les droits et l'état de la conversation. Ne relancez pas la tâche pour récupérer l'envoi.",
 "아직 결론이 없어요.": "Pas encore de conclusion.",
 "전체 회의 기록": "Historique complet de la réunion",
 "전달 복구": "Récupérer l'envoi",
 "원래 대화 열기": "Ouvrir la conversation d'origine",
 "전달 복구 방법": "Méthode de récupération de l'envoi",
 "복구 방법 선택": "Choisir une méthode de récupération",
 "미확인 부분부터 다시 보내기": "Renvoyer à partir de la partie non confirmée",
 "이미 받은 메시지 확인하기": "Confirmer un message déjà reçu",
 "다른 대화로 처음부터 보내기": "Tout envoyer depuis le début dans une autre conversation",
 "원래 대화에서 미확인 부분이 전송되지 않았는지 확인해 주세요. 이미 받은 부분을 다시 보내면 중복될 수 있어요.": "Vérifiez dans la conversation d'origine que la partie non confirmée n'a pas été envoyée. Renvoyer une partie déjà reçue peut créer un doublon.",
 "원래 대화에서 현재 미확인 부분을 받은 메시지의 ID를 입력해요. 확인 후 다음 부분부터 이어서 전달해요.": "Saisissez l'ID du message qui a reçu la partie actuellement non confirmée dans la conversation d'origine. Après vérification, l'envoi reprend à partir de la partie suivante.",
 "입력한 새 대화에 전체 결과를 처음부터 보내요. 기존 대화와 메시지 영수증은 복구 이력에 남아요.": "Le résultat complet est renvoyé depuis le début dans la nouvelle conversation saisie. L'ancienne conversation et les accusés de réception restent dans l'historique de récupération.",
 "원래 대화를 확인했고 미확인 부분을 다시 보내는 데 동의해요.": "J'ai vérifié la conversation d'origine et j'accepte de renvoyer la partie non confirmée.",
 "입력한 메시지가 현재 미확인 부분의 실제 수신 메시지임을 확인했어요.": "J'ai vérifié que le message saisi a bien reçu la partie actuellement non confirmée.",
 "새 목적지와 접근 권한을 확인했고 전체 결과를 보내는 데 동의해요.": "J'ai vérifié la nouvelle destination et les droits d'accès, et j'accepte d'envoyer le résultat complet.",
 "사람 계정의 복구 권한이 필요해요. 원래 대화를 확인한 뒤 방법을 선택해 주세요.": "Le compte d'une personne doit avoir le droit de récupération. Vérifiez la conversation d'origine avant de choisir une méthode.",
 "복구 내용 확인": "Vérifier les détails de la récupération",
 "확인한 내용으로 복구 요청": "Demander la récupération confirmée",
 "확인한 Discord 메시지 ID": "ID du message Discord vérifié",
 "Arkism 봇 ID": "ID du bot Arkism",
 "Discord 서버 ID": "ID du serveur Discord",
 "Discord 채널 ID": "ID du canal Discord",
