 "저장한 역할": "Rôle enregistré",
 "생각하는 깊이": "Profondeur de réflexion",
 "앞 단계 결과는 알아서 뒤에 붙여요": "Le résultat de l'étape précédente est ajouté automatiquement à la fin",
 "{{input}}이라고 쓴 자리에 앞 단계 결과가 들어가요": "Le résultat de l'étape précédente remplace {{input}} là où vous l'écrivez",
 "파일 바꾸기": "Modifier les fichiers",
 "안 함 · 읽기만": "Non · lecture seule",
 "함 · 한 번에 하나씩": "Oui · un à la fois",
 "켜면 이 노드가 일을 나눠 다른 전문가에게 맡기고 결과를 합쳐요. 하위 질문이 몇 개일지 미리 모를 때 써요.": "Si activé, ce nœud répartit le travail entre d'autres experts et fusionne les résultats. Utilisez-le quand vous ne savez pas à l'avance combien il y aura de sous-questions.",
 "모델 키를 찾지 못했어요. 설정 › 모델에서 키를 확인해 주세요.": "Clé du modèle introuvable. Vérifiez la clé dans Réglages › Modèles.",
 "주소에 연결하지 못했어요. 주소와 인터넷 연결을 확인해 주세요.": "Impossible de se connecter à l'adresse. Vérifiez l'adresse et votre connexion internet.",
 "상대 서버가 오류로 답했어요. 주소와 권한을 확인해 주세요.": "Le serveur distant a répondu par une erreur. Vérifiez l'adresse et les autorisations.",
