 "정해진 시간 안에 끝나지 않았어요.": "Ça ne s'est pas terminé dans le temps imparti.",
 "명령을 시작하지 못했어요.": "Impossible de lancer la commande.",
 "실행한 명령이 실패했어요.": "La commande exécutée a échoué.",
 "노드 설정을 확인해 주세요.": "Vérifiez les réglages du nœud.",
 "조건 식을 확인해 주세요.": "Vérifiez la condition.",
 "AI가 답하지 못했어요. 모델 연결을 확인해 주세요.": "L'IA n'a pas répondu. Vérifiez la connexion au modèle.",
 "목록이 너무 길어요 (최대 1000개).": "La liste est trop longue (1000 éléments maximum).",
 "반복할 목록을 찾지 못했어요. 목록 위치를 확인해 주세요.": "Impossible de trouver la liste à répéter. Vérifiez l'emplacement de la liste.",
 "이 Arkism이 모르는 노드가 있어요. 앱을 업데이트해 주세요.": "Cette version d'Arkism ne connaît pas l'un des nœuds. Mettez l'application à jour.",
 "하위 실행이 실패했어요.": "Une sous-exécution a échoué.",
 "앞선 호출 결과가 없어 자동으로 다시 하지 않았어요. 실패한 곳부터 다시 눌러 주세요.": "Aucun résultat d'appel précédent : aucune nouvelle tentative automatique. Relancez à partir de l'étape en échec.",
 "받는 곳을 찾지 못했어요. 알림 노드에서 받는 곳을 다시 골라 주세요.": "Destinataire introuvable. Choisissez de nouveau le destinataire dans le nœud de notification.",
