 "API 요금으로 쳤을 때": "Au tarif de l'API",
 "자세히 · 모델과 멈추는 조건": "Plus · modèle et limites d'arrêt",
 "이 워크플로우 이름을 정해 주세요\n목록에 크게 보이고, 코딩 에이전트 채팅에서 @이름으로 불러요. 나머지는 나중에 설정에서 바꿀 수 있어요.": "Donnez un nom à ce workflow\nIl s'affiche en grand dans la liste, et dans les discussions avec l'agent de code, on l'appelle par @nom. Vous pourrez modifier le reste plus tard dans les réglages.",
 "저장하고 실행": "Enregistrer et exécuter",
 "만들었어요. 설명·모델·배경 사진은 워크플로우 설정에서 바꿔요.": "C'est créé. Modifiez la description, le modèle et l'image de fond dans les réglages du workflow.",
 "연결 필요": "Connexion requise",
 "모델 연결하러 가기 ›": "Connecter un modèle ›",
 "이 모델은 제공자가 연결되지 않아 지금은 못 써요. 설정 › 에이전트에서 로그인하거나 키를 넣어요.": "Le fournisseur de ce modèle n'est pas connecté, donc il est inutilisable pour l'instant. Connectez-vous ou ajoutez une clé dans Réglages › Agents.",
