 "헤더 이름은 영문·숫자·-로 쓰고 값도 넣어 주세요. 키는 API 키 칸에 넣어요.": "Écrivez le nom de l'en-tête avec des lettres, des chiffres et -, et indiquez aussi une valeur. La clé se saisit dans le champ Clé API.",
 "개발 빌드": "Version de développement",
 "토큰은 Arkism에 암호화해 저장하고, 화면에는 끝 4자리만 보여요. 디스코드 개발자 포털에서 봇을 만들고 Message Content Intent를 켠 뒤 토큰을 넣어 주세요.": "Le jeton est enregistré chiffré dans Arkism, et seuls ses 4 derniers caractères s'affichent. Créez un bot dans le portail développeur Discord, activez Message Content Intent, puis collez le jeton.",
 "토큰은 Arkism에 저장하고, 화면에는 끝 4자리만 보여요. @BotFather로 만든 봇을 그룹이나 DM에 먼저 추가해 두세요.": "Le jeton est enregistré dans Arkism, et seuls ses 4 derniers caractères s'affichent. Ajoutez d'abord à un groupe ou à un DM le bot créé avec @BotFather.",
 "웹훅 주소는 Arkism에 저장하고, 화면에는 끝 4자리만 보여요. 슬랙의 Incoming Webhooks에서 만들어요.": "L'adresse du webhook est enregistrée dans Arkism, et seuls ses 4 derniers caractères s'affichent. Créez-la dans Incoming Webhooks de Slack.",
 "바꾸려면 팀·전문가 상세의 채널 연결에서 해요.": "Pour le modifier, utilisez la connexion de canal dans les détails de l'équipe ou de l'expert.",
