 "서버 AI로 다시 매기기": "Reclasser avec l'IA du serveur",
 "찾는 범위": "Étendue de la recherche",
 "기억 종류 (비워 두면 모두)": "Types de souvenirs (si vide, tous)",
 "이 기간 기억을 앞에 (부터)": "Mettre en premier les souvenirs de cette période (du)",
