 "순서 다시 매기기": "Reclassement",
 "서버 AI가 주제와 먼 기억 빼기": "L'IA du serveur écarte les souvenirs hors sujet",
 "서버 AI가 겹치는 기억 빼기": "L'IA du serveur écarte les souvenirs en double",
 "점수 하한 (0~1, 이보다 낮으면 빼요)": "Score minimal (0–1 ; en dessous, c'est écarté)",
 "다시 매긴 점수": "Score après reclassement",
