 "다시 매긴 점수 하한": "Seuil du score après reclassement",
 "주제와 멂": "Hors sujet",
 "겹침": "En double",
 "앞에 둔 기간": "Période mise en premier",
 "방법마다 무게": "Poids de chaque méthode",
 "단계별 제외": "Souvenirs écartés à chaque étape",
 "서버 AI가 매긴 순서": "Ordre défini par l'IA du serveur",
 "최근성 가산": "Facteur de récence",
 "결과 가중치": "Poids du résultat",
 "합친 점수는 방법마다 순위를 더한 값이라 작아요. 크기보다 순서를 보세요. 최근성과 결과 가중치는 합친 점수에 곱해요.": "Le score combiné additionne les rangs de chaque méthode, il est donc petit. Regardez l'ordre plutôt que la valeur. La récence et le poids du résultat se multiplient au score combiné.",
 "때": "Quand",
 "기억한 때": "Mémorisé le",
 "AI 답에서 가져온 초안이에요. 읽고 고쳐서 저장해야 규칙이 돼요.": "Ce brouillon vient d'une réponse de l'IA. Il ne devient une règle qu'une fois que vous l'avez lu, modifié et enregistré.",
 "뜻이 이어진 기억": "Liés par le sens",
 "지난 대화": "Conversations passées",
 "조각 그대로": "Morceaux tels quels",
 "이 공간의 기억 뽑기·막을 내용·이름 정리·찾기·답하는 방식·자동 정리·도구·활동 기록 설정을 모두 지우고 템플릿과 기본값을 따를까요?": "Effacer tous les réglages de cet espace (extraction des souvenirs, contenus bloqués, noms, recherche, façon de répondre, entretien automatique, outils, journal d'activité) et suivre le gabarit et les valeurs par défaut ?",
 "간결하게: 핵심만 · 자세하게: 맥락까지 · 원문 그대로: 말한 그대로 · 직접 쓰기: 아래 안내를 따라요 · 조각 그대로: 글을 나눈 조각마다 후보 하나 (모델 안 씀)": "Concis : l'essentiel · Détaillé : avec le contexte · Mot pour mot : tel que dit · Rédiger moi-même : suit le guide ci-dessous · Morceaux tels quels : un candidat par morceau de texte (sans modèle)",
 "한 번에 읽는 글 길이": "Longueur de texte lue d'un coup",
 "자세히 · 뽑는 방식 더 정하기": "Détails · Régler davantage l'extraction",
 "뽑을 때 목표": "Objectif de l'extraction",
 "예: 이 팀이 왜 그렇게 정했는지를 남겨요.": "Ex. : Garder la raison pour laquelle cette équipe a décidé ainsi.",
 "무엇을 기억으로 남길지 한두 문장으로 알려 줘요. 2000자까지.": "Dites en une ou deux phrases ce qu'il faut retenir comme souvenir. 2000 caractères maximum.",
 "긴 글을 이 글자 수로 나눠 읽어요 (500~12000). 비우면 물려받아요.": "Les longs textes sont lus par blocs de ce nombre de caractères (500–12000). Laissez vide pour hériter.",
 "원인과 결과도 후보로": "Causes et conséquences comme candidats",
 "한 일이 다른 일의 원인이면 그 연결도 후보로 만들어요.": "Quand un fait en a causé un autre, ce lien devient aussi un candidat.",
 "기억을 쓰는 언어": "Langue des souvenirs",
 "후보를 어떤 언어로 적을지예요. ‘말한 언어 그대로’는 내가 쓴 말을 따라요.": "La langue dans laquelle les candidats sont rédigés. « Langue d'origine » suit les mots que vous avez employés.",
 "기준 시간대": "Fuseau horaire de référence",
 "‘어제’·‘지난주’ 같은 말을 날짜로 바꿀 때 쓰는 시간대예요.": "Fuseau horaire utilisé pour transformer des mots comme « hier » ou « la semaine dernière » en dates.",
 "작업 상태를 후보로": "État du travail comme candidats",
 "작업 중간 저장과 인계를 ‘지금 어디까지 했는지’ 후보로 만들어요. 처음에는 꺼져 있어요.": "Les sauvegardes intermédiaires et les passations de travail deviennent des candidats « où en est le travail ». Désactivé au départ.",
 "자세히 · 뽑기 시험해 보기": "Détails · Tester l'extraction",
 "말한 언어 그대로": "Langue d'origine",
 "이름 붙은 뽑기 방식": "Styles d'extraction nommés",
 "아직 없어요. 파일 종류마다 다르게 뽑고 싶을 때 만들어요.": "Aucun pour l'instant. Créez-en un quand vous voulez extraire différemment selon le type de fichier.",
 "방식 이름": "Nom du style",
 "이름은 영어 소문자·숫자·-·_로, 겹치지 않게 써요.": "Utilisez des minuscules anglaises, des chiffres, - et _, sans doublon.",
 "공간 방식 따름": "Suivre l'espace",
 "이 방식의 뽑는 방식": "Façon d'extraire pour ce style",
 "이 방식의 글 길이": "Longueur de texte pour ce style",
 "공간 설정 따름": "Suivre le réglage de l'espace",
 "이 방식의 안내": "Consignes de ce style",
 "예: 회의록이면 결정과 담당자만 남겨요.": "Ex. : Pour un compte rendu de réunion, ne garder que les décisions et les responsables.",
 "이 방식의 목표": "Objectif de ce style",
 "방식 추가": "Ajouter un style",
 "기본으로 쓸 방식": "Style par défaut",
 "따로 고르지 않으면 이 방식으로 뽑아요.": "Ce style est utilisé si vous n'en choisissez pas d'autre.",
 "예: 어제 회의에서 배포는 금요일에 하지 않기로 했어요. 민수가 체크리스트를 맡았어요.": "Ex. : Lors de la réunion d'hier, nous avons décidé de ne pas déployer le vendredi. Minsu s'occupe de la checklist.",
