 "관찰 정리": "Entretien des observations",
 "어떤 프롬프트": "Quel prompt",
 "프롬프트 보기": "Voir le prompt",
 "저장하지 않은 설정으로 시험해요. 아무것도 저장하지 않아요.": "Teste avec les réglages non enregistrés. Rien n'est enregistré.",
 "실제로 뽑으면 서버 모델을 불러 모델 예산을 써요.": "Extraire pour de vrai appelle le modèle du serveur et utilise le budget du modèle.",
 "보낼 프롬프트 보기": "Voir le prompt à envoyer",
