 "높음, 보통, 낮음": "haute, normale, basse",
 "고를 수 있는 값": "Valeurs au choix",
 "고를 수 있는 값 (쉼표로 나눠요)": "Valeurs au choix (séparées par des virgules)",
 "태그로도 붙이기": "Ajouter aussi comme tag",
 "이 라벨을 기억의 태그로도 붙여요.": "Cette étiquette est aussi ajoutée au souvenir comme tag.",
 "라벨 추가": "Ajouter une étiquette",
 "가까운 뜻 잇기": "Relier les sens proches",
 "찾은 기억과 뜻이 가장 가까운 기억을 이어 붙여요. 처음에는 꺼져 있어요.": "Relie aux souvenirs trouvés ceux dont le sens est le plus proche. Désactivé au départ.",
 "똑같은 글": "Texte identique",
 "가까운 뜻": "Sens proche",
 "같이 보여 주고 ‘정정 검토 중’ 표시": "Afficher avec la mention « correction en cours d'examen »",
 "결정할 때까지 빼기": "Écarter jusqu'à décision",
 "세션 원문에서도 찾기": "Chercher aussi dans les transcriptions de session",
 "저장된 대화 원문도 찾는 길에 넣어요. 처음에는 꺼져 있어요.": "Les transcriptions de conversation enregistrées sont aussi incluses dans la recherche. Désactivé au départ.",
 "찾는 방법별 무게": "Poids par méthode de recherche",
 "1이 보통이에요. 크게 하면 그 방법으로 찾은 기억이 앞에 와요 (0.25~8).": "1 est la valeur normale. Plus c'est élevé, plus les souvenirs trouvés par cette méthode passent en premier (0.25–8).",
 "자세히 · 찾은 결과 거르기": "Détails · Filtrer les résultats",
 "관련 없는 결과 빼기": "Écarter les résultats sans rapport",
 "낱말만 우연히 맞고 뜻이 먼 기억을 빼요. 처음에는 켜져 있어요.": "Écarte les souvenirs où seuls les mots coïncident par hasard et dont le sens est éloigné. Activé au départ.",
 "정정을 기다리는 기억": "Souvenirs en attente de correction",
 "고쳐 달라는 후보가 있는 기억을 어떻게 보여 줄지예요.": "Comment afficher les souvenirs ayant un candidat de correction en attente.",
 "승인 전 후보도 보여 주기": "Afficher aussi les candidats non approuvés",
 "아직 승인하지 않은 후보를 ‘승인 전’ 표시와 함께 몇 개 보여 줘요. 확정된 기억처럼 쓰이지 않아요.": "Affiche quelques candidats pas encore approuvés, avec la mention « non approuvé ». Ils ne sont pas utilisés comme des souvenirs confirmés.",
 "정정되면 옛 사실 끝내기 제안": "Proposer de clore les anciens faits après une correction",
 "정정을 승인하면 옛 기억에 끝난 날짜를 붙이자고 제안해요. 내가 승인해야 바뀌어요.": "Quand vous approuvez une correction, il vous propose d'ajouter une date de fin à l'ancien souvenir. Rien ne change sans votre approbation.",
 "자세히 · 답할 때 읽는 것": "Détails · Ce que lisent les réponses",
 "적게": "Moins",
 "많이": "Plus",
 "기억과 관찰 모두": "Souvenirs et observations",
 "기억만": "Souvenirs seulement",
 "관찰만": "Observations seulement",
 "주제 요약 목록": "Liste des résumés par sujet",
 "주제 요약 읽기": "Lecture des résumés par sujet",
 "더 펼쳐 읽기": "Lire plus en détail",
 "읽을 기억의 양": "Quantité de souvenirs à lire",
 "답하기 전에 기억을 얼마나 많이 찾아 읽을지예요.": "C'est le nombre de souvenirs que l'on cherche et lit avant de répondre.",
 "읽을 종류": "Types à lire",
 "주제 요약은 빼고 답하기": "Répondre sans les résumés de sujet",
 "승인한 주제 요약을 읽지 않고 기억만으로 답해요.": "Répond avec les souvenirs seuls, sans lire les résumés de sujet approuvés.",
 "태그가 맞는 지시만 쓰기": "Utiliser seulement les consignes aux tags correspondants",
 "태그를 붙인 지시는 같은 태그로 물을 때만 따라요.": "Une consigne avec tag n'est suivie que si la question porte le même tag.",
 "도구 한 번에 읽는 양 (토큰)": "Quantité lue par appel d'outil (tokens)",
 "비우면 기본값을 써요.": "Laissez vide pour utiliser la valeur par défaut.",
 "자세히 · 관찰 정리 방식": "Détails · Méthode de tri des observations",
 "자세히 · 주제 요약 기본값": "Détails · Valeurs par défaut des résumés de sujet",
 "모두 한 묶음": "Tout dans un seul groupe",
 "태그 조합마다": "Par combinaison de tags",
 "태그마다": "Par tag",
 "모든 태그 조합마다": "Pour chaque combinaison de tags",
 "묶음마다 관찰 수": "Observations par groupe",
 "한 번에 정리할 묶음": "Groupes à trier à la fois",
 "동시에 정리": "Tris simultanés",
 "관찰을 만들 때 목표": "Objectif pour créer les observations",
 "예: 반복되는 실수와 그 해결을 관찰로 남겨요.": "Ex. : garder les erreurs répétées et leurs solutions sous forme d'observations.",
 "묶는 방식": "Façon de regrouper",
 "어떤 기억끼리 모아 관찰을 만들지예요.": "Indique quels souvenirs sont réunis pour créer des observations.",
 "기본값 · 모두 한 묶음": "Par défaut · Tout dans un seul groupe",
 "정리 전략 규칙 (JSON)": "Règles de stratégie de tri (JSON)",
 "default_scopes · strategies · scope_limits 를 적어요. 태그 모양으로 어떤 전략이 어떤 묶음을 맡을지 정해요.": "Renseignez default_scopes · strategies · scope_limits. Selon la forme des tags, vous choisissez quelle stratégie gère quel groupe.",
 "JSON을 읽을 수 없거나 모르는 이름이 있어요. 저장하지 않았어요.": "Le JSON est illisible ou contient un nom inconnu. Rien n'a été enregistré.",
 "전략 미리 보기": "Aperçu des stratégies",
 "전략이 없어 모두 기본 방식으로 정리해요.": "Il n'y a aucune stratégie : tout est trié de la façon par défaut.",
 "직접 할 때만": "Seulement quand je le fais",
 "기억이 바뀌면": "Quand les souvenirs changent",
 "6시간": "6 heures",
 "일주일": "Une semaine",
 "언제 새로 고칠지": "Quand actualiser",
 "새 주제 요약을 만들 때 따로 정하지 않으면 이대로 해요. 새로 고친 요약도 내가 승인해야 쓰여요.": "Ces réglages s'appliquent à un nouveau résumé de sujet si vous n'en choisissez pas d'autres. Un résumé actualisé n'est utilisé qu'après votre approbation.",
 "정해진 시각 (cron)": "Heures fixes (cron)",
 "다음 시각 보기": "Voir les prochaines heures",
 "정해진 시각 (cron, UTC)": "Heures fixes (cron, UTC)",
 "다섯 칸으로 써요. 예: 0 9 * * 1 = 월요일 9시(UTC).": "Écrivez cinq champs. Ex. : 0 9 * * 1 = le lundi à 9 h (UTC).",
 "관찰 정리 뒤에 고치기": "Actualiser après le tri des observations",
 "관찰을 정리하고 나면 요약도 새로 고쳐요.": "Une fois les observations triées, les résumés sont aussi actualisés.",
 "가장 짧은 간격": "Intervalle minimal",
 "요약을 이보다 자주 고치지 않아요.": "Les résumés ne sont pas actualisés plus souvent que cela.",
 "cron을 먼저 넣어 주세요.": "Veuillez d'abord saisir un cron.",
 "다음 실행 시각": "Prochaines heures d'exécution",
 "cron을 읽을 수 없어요. 다섯 칸인지 확인해 주세요.": "Impossible de lire le cron. Vérifiez qu'il compte cinq champs.",
