 "빠진 부분에서 나온 기억 후보 {0}개는 그대로 남아 있어요. 필요 없으면 '확인해 주세요'에서 버려 주세요.": "{0} mémoires candidates issues des parties supprimées sont toujours là. Si vous n'en avez pas besoin, abandonnez-les dans « Veuillez vérifier ».",
 "보낸 기록을 불러오지 못했어요. {0}": "Impossible de charger l'historique des envois. {0}",
