 "'{0}' 태그를 '{1}'에 합칠까요?": "Fusionner le tag '{0}' dans '{1}' ?",
 "'{0}' 태그 이름을 '{1}'(으)로 바꿀까요?": "Renommer le tag '{0}' en '{1}' ?",
 "기억 {0}개가 '{1}' 태그로 바뀌어요.": "{0} mémoires recevront le tag '{1}'.",
 "기억 {0}개가 바뀌어요.": "{0} mémoires seront modifiées.",
 "후보 {0}개를 가져왔어요. 이미 있는 기억 {1}개는 건너뛰었고, 받지 않은 것 {2}개예요.": "{0} candidats importés. {1} mémoires déjà présentes ignorées, {2} non acceptées.",
 "{0}. 서버 주소와 네트워크를 확인하세요.": "{0}. Vérifiez l'adresse du serveur et le réseau.",
 "웹 화면으로 이 서버({0})에 접속 토큰으로 연결돼 있어요. SSH 연결, 이 PC에서 쓰기, 백업, 에이전트 연결은 Arkism 데스크톱 앱에서 할 수 있어요.": "Cette page web est connectée à ce serveur ({0}) avec un jeton d'accès. La connexion SSH, l'utilisation sur ce PC, les sauvegardes et la connexion des agents se font dans l'application de bureau Arkism.",
 "{0}를 찾지 못해 대화에서 기억 후보를 뽑지 못해요. Claude Code나 Codex를 설치하고 로그인하거나, 다른 모델을 고르세요.": "Impossible de trouver {0} : aucun souvenir candidat ne peut être extrait des conversations. Installez Claude Code ou Codex et connectez-vous, ou choisissez un autre modèle.",
 "{0}에 로그인하면 대화에서 기억 후보를 뽑기 시작해요.": "Connectez-vous à {0} pour que des souvenirs candidats soient extraits de vos conversations.",
 "{0} 로그인이 끝났거나 사용 한도에 걸렸을 수 있어요. 다시 로그인하거나 다른 모델을 고르세요.": "Votre connexion à {0} a peut-être expiré ou la limite d'utilisation est atteinte. Reconnectez-vous ou choisissez un autre modèle.",
 "{0}에 Arkism을 이었어요. 열려 있는 에이전트는 다시 시작하세요.": "Arkism est connecté à {0}. Redémarrez les agents ouverts.",
 "{0}로 대화에서 기억 후보를 뽑아요.": "{0} extrait des souvenirs candidats de vos conversations.",
 "에이전트 지침 파일에서 기억 {0}개를 찾았어요. 가져오면 검토 대기로 가고, 승인한 것만 저장돼요.": "{0} souvenirs trouvés dans les fichiers d'instructions de vos agents. Une fois importés, ils attendent votre relecture et seuls ceux que vous approuvez sont enregistrés.",
 "{0}가지를 고쳤어요. 다시 시도를 눌러 보세요.": "{0} problèmes corrigés. Appuyez sur Réessayer.",
 "남은 문제 {0}개: {1}": "{0} problèmes restants : {1}",
